// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        vm.assume(caller != address(this));

        vm.deal(caller, 1 ether);

        bool ok;
        bytes memory returndata;

        vm.prank(caller);
        try c.withdrawAll(address(0)) {
            ok = true;
            returndata = "";
        } catch (bytes memory reason) {
            ok = false;
            returndata = reason;
        }

        assertTrue(!ok && returndata.length == 0);
    }
}
